package thaumcraft.verification;

import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import net.minecraft.client.*;
import net.minecraft.world.*;
import net.minecraft.core.Direction;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.client.event.*;

final class MechanicsLiveClient {
    private static int statusTicks,stage=Integer.getInteger("thaumcraft.mechanics.start",0),wait,frames;private static boolean started,ready,done,clicked,bellSelected,bellMarked,resetSent;
    private static final List<String> captures=new ArrayList<>();
    static void install(net.neoforged.bus.api.IEventBus bus){
        bus.addListener((net.neoforged.fml.event.lifecycle.FMLClientSetupEvent e)->e.enqueueWork(()->{var mc=Minecraft.getInstance();mc.options.skipMultiplayerWarning=true;mc.options.onboardAccessibility=false;mc.options.pauseOnLostFocus=false;mc.options.save();long handle=mc.getWindow().getWindow();org.lwjgl.glfw.GLFW.glfwSetWindowAttrib(handle,org.lwjgl.glfw.GLFW.GLFW_FOCUS_ON_SHOW,org.lwjgl.glfw.GLFW.GLFW_FALSE);org.lwjgl.glfw.GLFW.glfwShowWindow(handle);org.lwjgl.glfw.GLFW.glfwRestoreWindow(handle);}));
        net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((ClientTickEvent.Post e)->{try{tick();}catch(Throwable t){fail(t);}});
        net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((RenderLevelStageEvent e)->{if(stage!=3&&stage!=8&&stage!=17&&stage!=22&&stage!=23&&stage!=25&&stage!=29&&stage!=30&&stage!=33&&e.getStage()==RenderLevelStageEvent.Stage.AFTER_LEVEL&&ready&&!done&&++frames>3)try{capture();}catch(Throwable t){fail(t);}});
        net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((RenderGuiEvent.Post e)->{if(stage==30&&ready&&!done&&++frames>3)try{capture();}catch(Throwable t){fail(t);}});
        net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((ScreenEvent.Render.Post e)->{if((stage==3||stage==8||stage==17||stage==22||stage==23||stage==25||stage==29||stage==33)&&ready&&!done&&++frames>3)try{capture();}catch(Throwable t){fail(t);}});
    }
    private static void request()throws Exception{if(Integer.getInteger("thaumcraft.mechanics.start",0)>=29&&Minecraft.getInstance().screen!=null)Minecraft.getInstance().setScreen(null);wait=frames=0;clicked=ready=false;Minecraft.getInstance().options.keyShift.setDown(false);if(Minecraft.getInstance().screen instanceof JarInset||Minecraft.getInstance().screen instanceof TooltipInset)Minecraft.getInstance().setScreen(null);Files.writeString(MechanicsLiveScene.root().resolve("request.json"),Integer.toString(stage));}
    private static void tick()throws Exception {var mc=Minecraft.getInstance();if(Integer.getInteger("thaumcraft.mechanics.start",0)==9&&++statusTicks%20==0)Files.writeString(MechanicsLiveScene.root().resolve("bell-client-state.json"),new GsonBuilder().setPrettyPrinting().create().toJson(Map.of("stage",stage,"wait",wait,"clicked",clicked,"marked",bellMarked,"screen",String.valueOf(mc.screen),"overlay",String.valueOf(mc.getOverlay()),"hand",mc.player==null?"no player":mc.player.getMainHandItem().toString(),"data",mc.player==null?"":mc.player.getMainHandItem().getComponents().toString())));if(done||mc.level==null||mc.player==null||mc.getOverlay()!=null)return;
        if(!started){if(++wait<50)return;started=true;mc.options.fov().set(70);mc.options.guiScale().set(1);mc.options.gamma().set(.5d);mc.options.bobView().set(false);mc.options.hideGui=true;request();return;}
        var path=MechanicsLiveScene.root().resolve("ready.json");if(!Files.exists(path)||Integer.parseInt(Files.readString(path).trim())!=stage)return;
        mc.player.setYRot(stage==31||stage==32?180:stage==34||stage==35?180:stage==36?135:stage==21?153.4f:stage>=24||stage==13||stage==14||stage==20||stage==16&&bellSelected?135:180);mc.player.yRotO=mc.player.getYRot();mc.player.setXRot(stage==32?-90:stage==31?-18:stage==34||stage==35||stage==36?3:stage==27?23:stage==24||stage==25||stage==26?21:stage==28?8.3f:stage==21?15:stage==15?40:stage==13?8.3f:stage==14?22:stage==16&&bellSelected?20:stage==4?8:stage>=18?3:stage>=9?10:3);mc.player.xRotO=mc.player.getXRot();mc.player.setDeltaMovement(Vec3.ZERO);
        if(stage==5){mc.options.keyShift.setDown(true);mc.player.input.shiftKeyDown=true;mc.player.setShiftKeyDown(true);}
        if(++wait<(stage>=18?10:45))return;
        if(stage==34&&!clicked){clicked=true;var result=mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(MechanicsLiveScene.CENTER.getCenter(),Direction.SOUTH,MechanicsLiveScene.CENTER,false));if(!result.consumesAction())throw new AssertionError("Actual ore scan click rejected");wait=0;return;}
        if(stage==18&&!clicked){clicked=true;mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(MechanicsLiveScene.CENTER.getCenter(),Direction.SOUTH,MechanicsLiveScene.CENTER,false));wait=0;return;}

        if((stage==1||stage==2)&&!clicked){clicked=true;var p=MechanicsLiveScene.CENTER;var result=mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(p.getCenter(),Direction.SOUTH,p,false));if(!result.consumesAction())throw new AssertionError("Native pickaxe click rejected");wait=35;return;}
        if(stage==16&&!clicked){var golem=java.util.stream.StreamSupport.stream(mc.level.entitiesForRendering().spliterator(),false).filter(e->e instanceof thaumcraft.entities.ThaumicGolem).findFirst().orElseThrow();mc.gameMode.interact(mc.player,golem,InteractionHand.MAIN_HAND);clicked=bellSelected=true;wait=20;return;}
        if(stage==9){if(!clicked){var golem=java.util.stream.StreamSupport.stream(mc.level.entitiesForRendering().spliterator(),false).filter(e->e instanceof thaumcraft.entities.ThaumicGolem).min(java.util.Comparator.comparingDouble(mc.player::distanceToSqr)).orElseThrow();mc.gameMode.interact(mc.player,golem,InteractionHand.MAIN_HAND);clicked=bellSelected=true;wait=35;return;}if(thaumcraft.items.GolemBellItem.selected(mc.player.getMainHandItem(),mc.level)==null)return;if(!bellMarked&&wait>65){mc.player.setYRot(165);mc.player.setXRot(45);if(!(mc.hitResult instanceof BlockHitResult hit)||hit.getType()!=HitResult.Type.BLOCK)return;mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,hit);bellMarked=true;wait=35;return;}}
        if(stage==10&&!resetSent){net.minecraft.client.KeyMapping.click(com.mojang.blaze3d.platform.InputConstants.Type.KEYSYM.getOrCreate(org.lwjgl.glfw.GLFW.GLFW_KEY_F));resetSent=true;wait=35;return;}
        if(stage==10&&wait>=60){if(!thaumcraft.items.GolemBellItem.markers(mc.player.getMainHandItem()).isEmpty())throw new AssertionError("Native F did not reset bell markers");if(thaumcraft.items.GolemBellItem.selected(mc.player.getMainHandItem(),mc.level)==null)throw new AssertionError("F lost selection or swapped bell offhand");}
        if((stage==17||stage==22||stage==23)&&wait==50){mc.options.guiScale().set(1);mc.resizeDisplay();var screen=new ScanInventory(mc.player,stage==23);mc.setScreen(screen);org.lwjgl.glfw.GLFW.glfwSetCursorPos(mc.getWindow().getWindow(),mc.getWindow().getScreenWidth()/2d-72,mc.getWindow().getScreenHeight()/2d+(stage==23?67:9));}
        if((stage==29||stage==33)&&wait==10){mc.options.guiScale().set(3);mc.resizeDisplay();if(stage==29)mc.setScreen(new NativeJarInventory(mc.player));}
        if(stage==30){mc.options.hideGui=false;mc.player.setYRot(180);mc.player.yRotO=180;}
        if(stage==31)mc.options.hideGui=true;
        if(stage==25&&wait==50)mc.setScreen(new JarInset());
        if(stage==3&&wait==120)mc.setScreen(new JarInset());
        if(stage==9&&(!bellMarked||!Files.exists(MechanicsLiveScene.root().resolve("bell-server-clicks.json"))))return;
        if(wait>=(stage==17||stage==22||stage==23?100:stage==21?100:stage==29||stage==33?75:stage>=18?20:stage==3?150:60)){if(stage==5&&!(mc.hitResult instanceof BlockHitResult hit&&hit.getType()==HitResult.Type.BLOCK))throw new AssertionError("Shovel preview lacks native block target");if(stage==8&&!(mc.screen instanceof thaumcraft.client.GolemScreen))throw new AssertionError("Native golem screen did not open");ready=true;}
    }
    private static void capture()throws Exception{var mc=Minecraft.getInstance();String name=new String[]{"00-stone-wall-before.png","01-ore-through-wall.png","02-water-lava-through-wall.png","03-jarred-node.png","04-all-materials-resource-carry.png","05-shovel-shift-preview.png","06-stabilizers-converter.png","07-node-types.png","08-golem-menu.png","09-bell-links-a.png","10-bell-native-f-reset.png","11-single-jar-aspect.png","12-node-hud.png","13-node-hud-orbit.png","14-jar-item-billboard.png","15-crucible-water.png","16-selected-golem-range.png","17-inventory-aspect-panel.png","18-ore-fixed-origin.png","19-ore-walk-back.png","20-ore-orbit.png","21-fishing-cast.png","22-already-scanned-tooltip.png","23-thaumometer-tooltip.png","24-crucible-solid-legs.png","25-crucible-native-inventory.png","26-crucible-filled-oblique.png","27-node-jar-facing.png","28-stabilizer-bubble-opacity.png","29-native-jar-slot.png","30-native-jar-hand.png","31-crucible-under-side.png","32-crucible-under-bottom.png","33-use-golem-checkboxes.png","34-ores-water-wall.png","35-ores-walk-back.png","36-ores-orbit.png"}[stage];if(stage==9&&captures.contains(name))name="09-bell-links-b.png";mc.renderBuffers().bufferSource().endBatch();try(var img=Screenshot.takeScreenshot(mc.getMainRenderTarget())){img.writeToFile(MechanicsLiveScene.root().resolve(name));}if(stage==34||stage==35||stage==36){var expiry=thaumcraft.client.OreScanEffects.class.getDeclaredField("expires");expiry.setAccessible(true);Files.writeString(MechanicsLiveScene.root().resolve("ore-life-"+stage+".json"),new GsonBuilder().setPrettyPrinting().create().toJson(Map.of("remaining",expiry.getLong(null)-mc.level.getGameTime(),"gameTime",mc.level.getGameTime())));var field=thaumcraft.client.OreScanEffects.class.getDeclaredField("markers");field.setAccessible(true);var values=(List<?>)field.get(null);Files.writeString(MechanicsLiveScene.root().resolve("native-ore-packet-"+stage+".json"),new GsonBuilder().setPrettyPrinting().create().toJson(values));if(values.isEmpty())throw new AssertionError("Ore scan packet has no native markers");}if(stage==4){var carried=new ArrayList<Map<String,Object>>();for(var e:mc.level.entitiesForRendering())if(e instanceof thaumcraft.entities.ThaumicGolem g)carried.add(Map.of("material",g.material().name(),"core",g.core(),"action",g.action(),"held",g.displayCarried().toString(),"data",g.displayCarried().getComponents().toString()));Files.writeString(MechanicsLiveScene.root().resolve("golem-carried-data.json"),new GsonBuilder().setPrettyPrinting().create().toJson(carried));}if(stage==9&&!captures.contains(name))verifyRibbon();captures.add(name);ready=false;if(stage==9&&name.endsWith("-a.png")){wait=40;frames=0;return;}if(++stage==(Integer.getInteger("thaumcraft.mechanics.start",0)>=29?37:Integer.getInteger("thaumcraft.mechanics.start",0)>=24?29:Integer.getInteger("thaumcraft.mechanics.start",0)>=11?24:Integer.getInteger("thaumcraft.mechanics.start",0)==9?11:9)||Integer.getInteger("thaumcraft.mechanics.start",0)==4&&stage==5){done=true;Files.writeString(MechanicsLiveScene.root().resolve(Integer.getInteger("thaumcraft.mechanics.start",0)==9?"bell-result.json":Integer.getInteger("thaumcraft.mechanics.start",0)==4?"golem-carry-result.json":"result.json"),new GsonBuilder().setPrettyPrinting().create().toJson(Map.of("finished",true,"captures",captures,"nativePickaxeClick",Integer.getInteger("thaumcraft.mechanics.start",0)==0,"nativeBellEntityClick",bellSelected,"nativeBellBlockClick",bellMarked,"nativeBellFReset",resetSent))+"\n");mc.stop();}else request();}
    private static void verifyRibbon()throws Exception{
        var file=MechanicsLiveScene.root().getParent().resolve("original-bell/native-ribbon-vertices.json");var reference=Files.readString(file);Files.writeString(MechanicsLiveScene.root().resolve("bell-reference-ribbon-vertices.json"),reference);var d=JsonParser.parseString(reference).getAsJsonObject();if(!d.get("timeStable").getAsBoolean())throw new AssertionError("Original ribbon clock crossed capture boundary");var o=d.getAsJsonArray("origin");var origin=new Vec3(o.get(0).getAsDouble(),o.get(1).getAsDouble(),o.get(2).getAsDouble());var marker=new thaumcraft.entities.GolemMarker(net.minecraft.world.level.Level.OVERWORLD,new net.minecraft.core.BlockPos(4,64,0),Direction.UP,14);var points=thaumcraft.client.GolemLinkOverlay.points(origin,marker,d.get("quality").getAsInt(),d.get("time").getAsFloat(),d.get("height").getAsDouble());var nativeVertices=d.getAsJsonArray("vertices");if(nativeVertices.size()!=points.size()*2)throw new AssertionError("Ribbon subdivision differs from native original");double maxPosition=0,maxUv=0;int maxAlpha=0;for(int i=0;i<points.size();i++)for(int edge=0;edge<2;edge++){var point=points.get(i);var p=(edge==0?point.low():point.high()).subtract(origin);var raw=nativeVertices.get(i*2+edge).getAsJsonArray();maxPosition=Math.max(maxPosition,Math.max(Math.abs(p.x-raw.get(0).getAsDouble()),Math.max(Math.abs(p.y-raw.get(1).getAsDouble()),Math.abs(p.z-raw.get(2).getAsDouble()))));maxUv=Math.max(maxUv,Math.abs(point.u()-raw.get(3).getAsDouble()));maxAlpha=Math.max(maxAlpha,Math.abs((int)(point.alpha()*255)-raw.get(5).getAsInt()));}var result=Map.of("nativeVertices",nativeVertices.size(),"maxPositionError",maxPosition,"maxUvError",maxUv,"maxAlphaByteError",maxAlpha,"passed",maxPosition<.0001&&maxUv<.0001&&maxAlpha<=1);Files.writeString(MechanicsLiveScene.root().resolve("bell-native-ribbon-comparison.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result));if(!(Boolean)result.get("passed"))throw new AssertionError("Ribbon geometry differs from original: "+result);
    }
    private static final class NativeJarInventory extends net.minecraft.client.gui.screens.inventory.InventoryScreen {
        NativeJarInventory(net.minecraft.world.entity.player.Player player){super(player);}
        @Override public void render(net.minecraft.client.gui.GuiGraphics g,int x,int y,float partial){super.render(g,-100,-100,partial);g.flush();}
    }
    private static final class ScanInventory extends net.minecraft.client.gui.screens.inventory.InventoryScreen {
        private final boolean scanner;
        ScanInventory(net.minecraft.world.entity.player.Player player,boolean scanner){super(player);this.scanner=scanner;}
        @Override public void render(net.minecraft.client.gui.GuiGraphics graphics,int x,int y,float partial){super.render(graphics,getGuiLeft()+16,getGuiTop()+(scanner?150:92),partial);graphics.flush();}
    }
    private static final class TooltipInset extends net.minecraft.client.gui.screens.Screen {
        TooltipInset(){super(net.minecraft.network.chat.Component.literal("Native inventory tooltip"));}
        @Override public boolean isPauseScreen(){return false;}
        @Override public void render(net.minecraft.client.gui.GuiGraphics graphics,int x,int y,float partial){graphics.renderTooltip(font,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIRT),420,340);graphics.flush();}
    }
    private static final class JarInset extends net.minecraft.client.gui.screens.Screen {
        JarInset(){super(net.minecraft.network.chat.Component.literal("Node jar native item"));}
        @Override public boolean isPauseScreen(){return false;}
        @Override public void render(net.minecraft.client.gui.GuiGraphics g,int x,int y,float partial){g.fill(750,490,945,700,0xe0202020);g.drawString(font,"Native inventory",765,500,0xffffffff,false);g.pose().pushPose();g.pose().translate(790,540,0);g.pose().scale(7,7,7);g.renderItem(Minecraft.getInstance().player.getMainHandItem(),0,0);g.pose().popPose();g.flush();}
    }
    private static void fail(Throwable t){t.printStackTrace();done=true;try{Files.writeString(MechanicsLiveScene.root().resolve("error.txt"),t.toString());}catch(Exception ignored){}Minecraft.getInstance().stop();}
}
